            }
            const record = content;
            if (Array.isArray(record.messages))
                return extractChatMessages(record.messages);
            if (Array.isArray(record.chat))
                return extractChatMessages(record.chat);
            if (Array.isArray(record.data))
                return extractChatMessages(record.data);
            const message = typeof record.mes === 'string' ? record.mes : typeof record.message === 'string' ? record.message : '';
